SELECT *
FROM (
		SELECT ROWNUM rnum, a.*
		FROM (
			SELECT *
			FROM TOUR_DESTINATION
			WHERE CONTENT_TYPE_ID = #{contentTypeId}
			ORDER BY CONTENT_ID ) a
		)
WHERE rnum BETWEEN #{startRow} AND #{endRow}

    SELECT *
	FROM (
			SELECT ROWNUM rnum, a.*
			FROM (
				SELECT *
				FROM TOUR_DESTINATION
				WHERE LCLS_SYSTM3 = #{category}
				ORDER BY LCLS_SYSTM3 ) a
			)
	WHERE rnum BETWEEN #{startRow} AND #{endRow}
